const updateResource = `-- name: UpdateResource :one
UPDATE resources
SET name = $2, description = $3, workspace_id = $4, status = $5, monitoring_enabled = $6
WHERE id = $1 AND deleted_at IS NULL
RETURNING id, workspace_id, name, resource_type, status, description, created_at, updated_at, deleted_at, monitoring_enabled
`

type UpdateResourceParams struct {
	ID                uuid.UUID   `json:"id"`
	Name              string      `json:"name"`
	Description       pgtype.Text `json:"description"`
	WorkspaceID       uuid.UUID   `json:"workspace_id"`
	Status            string      `json:"status"`
	MonitoringEnabled bool        `json:"monitoring_enabled"`
}

func (q *Queries) UpdateResource(ctx context.Context, arg UpdateResourceParams) (Resource, error) {
	row := q.db.QueryRow(ctx, updateResource,
		arg.ID,
		arg.Name,
		arg.Description,
		arg.WorkspaceID,
		arg.Status,
		arg.MonitoringEnabled,
	)
	var i Resource
	err := row.Scan(
		&i.ID,
		&i.WorkspaceID,
		&i.Name,
		&i.ResourceType,
		&i.Status,
		&i.Description,
		&i.CreatedAt,
		&i.UpdatedAt,
		&i.DeletedAt,
		&i.MonitoringEnabled,
	)
	return i, err
}

const updateResourceStatus = `-- name: UpdateResourceStatus :one
UPDATE resources
SET status = $2
WHERE id = $1
RETURNING id, workspace_id, name, resource_type, status, description, created_at, updated_at, deleted_at, monitoring_enabled
`

type UpdateResourceStatusParams struct {
	ID     uuid.UUID `json:"id"`
	Status string    `json:"status"`
}

func (q *Queries) UpdateResourceStatus(ctx context.Context, arg UpdateResourceStatusParams) (Resource, error) {
	row := q.db.QueryRow(ctx, updateResourceStatus, arg.ID, arg.Status)
	var i Resource
	err := row.Scan(
		&i.ID,
		&i.WorkspaceID,
		&i.Name,
		&i.ResourceType,
		&i.Status,
		&i.Description,
		&i.CreatedAt,
		&i.UpdatedAt,
		&i.DeletedAt,
		&i.MonitoringEnabled,
	)
	return i, err
}
